const HELPER="#!/usr/local/bin/prhm-node\n'use strict';\nconst fs=require('fs');\nconst path=require('path');\nconst crypto=require('crypto');\nconst cp=require('child_process');\n\nconst ACTION='leadops_language_gate_v1';\nconst SCORER='/home/drtarjomeh/leadops/runtime-v3/leadops-parscoders-score';\nconst EXPECTED_V3_SHA='61459e3934107d25a88cc4c375c880bb4faa6f59df755f62c46d62b51244cb61';\nconst PASSWORD_FILE='/etc/prhm-p0-db-helper/postgres_superuser_password';\nconst STATE_DIR='/var/lib/prhm-agent-selfmaint-exec/leadops-language-gate-v1';\nconst RESULT_FILE=path.join(STATE_DIR,'latest.json');\nconst LOCK_DIR=path.join(STATE_DIR,'lock');\nconst MAX_TARGETS=100;\n\nconst LANGS=[\n  {code:'en',labels:['انگلیسی','english']},\n  {code:'fa',labels:['فارسی','farsi','persian']},\n  {code:'ar',labels:['عربی','arabic']},\n  {code:'ru',labels:['روسی','russian']},\n  {code:'zh',labels:['چینی','chinese','mandarin']},\n  {code:'ur',labels:['اردو','urdu']},\n  {code:'es',labels:['اسپانیایی','spanish']},\n  {code:'it',labels:['ایتالیایی','italian']},\n  {code:'de',labels:['آلمانی','german']},\n  {code:'fr',labels:['فرانسوی','french']}\n];\n\nfunction shaBuffer(b){return crypto.createHash('sha256').update(b).digest('hex');}\nfunction shaFile(f){return shaBuffer(fs.readFileSync(f));}\nfunction countOf(text,needle){return text.split(needle).length-1;}\nfunction replaceOnce(text,anchor,replacement,label){const i=text.indexOf(anchor);if(i<0)throw Error('anchor_missing:'+label);if(text.indexOf(anchor,i+anchor.length)>=0)throw Error('anchor_not_unique:'+label);return text.slice(0,i)+replacement+text.slice(i+anchor.length);}\nfunction exec(file,args,{input,env,allowFailure=false,timeout=30000}={}){const r=cp.spawnSync(file,args,{input,env:env||process.env,encoding:'utf8',timeout,maxBuffer:4*1024*1024,stdio:['pipe','pipe','pipe']});if(r.error)throw Error('exec_error:'+path.basename(file)+':'+r.error.message);if(!allowFailure&&r.status!==0)throw Error('exec_failed:'+path.basename(file)+':'+r.status+':'+String(r.stderr||r.stdout||'').slice(0,1500));return r;}\nfunction systemctl(args,{allowFailure=false,timeout=30000}={}){return exec('/usr/bin/systemctl',args,{allowFailure,timeout});}\nfunction sleep(ms){Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,ms);}\nfunction waitActive(unit,attempts=40){for(let i=0;i<attempts;i++){const r=systemctl(['is-active',unit],{allowFailure:true,timeout:10000});if(String(r.stdout||'').trim()==='active')return true;sleep(500);}return false;}\nfunction langPattern(lang){return '('+lang.labels.map(x=>x.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&')).join('|')+')';}\nfunction pairPattern(src,dst){return '((از[[:space:]]+)?'+langPattern(src)+'[[:space:]]+به[[:space:]]+'+langPattern(dst)+'|'+langPattern(src)+'[[:space:]]+(to|2)[[:space:]]+'+langPattern(dst)+')';}\nfunction directionPairs(){const fa=LANGS.find(x=>x.code==='fa');const out=[];for(const l of LANGS){if(l.code==='fa')continue;out.push({src:l.code,dst:'fa',re:pairPattern(l,fa)});out.push({src:'fa',dst:l.code,re:pairPattern(fa,l)});}return out;}\nconst PAIRS=directionPairs();\nfunction sourceCase(expr){return 'CASE\\n'+PAIRS.map(p=>`      WHEN ${expr} ~ '${p.re}' THEN '${p.src}'`).join('\\n')+'\\n      ELSE NULL\\n    END';}\nfunction targetCase(expr){return 'CASE\\n'+PAIRS.map(p=>`      WHEN ${expr} ~ '${p.re}' THEN '${p.dst}'`).join('\\n')+'\\n      ELSE NULL\\n    END';}\n\nfunction buildScorerV4(input){\n  if(countOf(input,'rules-v3-parscoders')!==5)throw Error('unexpected_rules_v3_occurrence_count:'+countOf(input,'rules-v3-parscoders'));\n  let out=input.split('rules-v3-parscoders').join('rules-v4-parscoders');\n  out=replaceOnce(out,'#!/usr/bin/env bash\\n','#!/usr/bin/env bash\\n# compatibility-marker: rules-v3-parscoders\\n# language-gate: rules-v4-parscoders\\n','compat_marker');\n  const dimAnchor='    END::numeric AS strategic_value_score,\\n    least(100,';\n  const dimReplacement='    END::numeric AS strategic_value_score,\\n    '+sourceCase('b.corpus').replace(/\\n/g,'\\n    ')+' AS detected_language_source,\\n    '+targetCase('b.corpus').replace(/\\n/g,'\\n    ')+' AS detected_language_target,\\n    least(100,';\n  out=replaceOnce(out,dimAnchor,dimReplacement,'language_dimensions');\n  const gateAnchor=`  CASE\\n    WHEN t.total_score >= 82 THEN 'HIGH_PRIORITY'\\n    WHEN t.total_score >= 68 THEN 'GOOD'\\n    ELSE 'MANUAL_REVIEW'\\n  END AS recommendation,\\n  CASE\\n    WHEN t.total_score >= 68 THEN 'WAITING_APPROVAL'\\n    ELSE 'MANUAL_REVIEW'\\n  END AS next_status,`;\n  const gateReplacement=`  CASE\\n    WHEN t.service_category IN ('TRANSLATION','GENERAL_TRANSLATION') AND (t.detected_language_source IS NULL OR t.detected_language_target IS NULL) THEN 'MANUAL_REVIEW'\\n    WHEN t.total_score >= 82 THEN 'HIGH_PRIORITY'\\n    WHEN t.total_score >= 68 THEN 'GOOD'\\n    ELSE 'MANUAL_REVIEW'\\n  END AS recommendation,\\n  CASE\\n    WHEN t.service_category IN ('TRANSLATION','GENERAL_TRANSLATION') AND (t.detected_language_source IS NULL OR t.detected_language_target IS NULL) THEN 'MANUAL_REVIEW'\\n    WHEN t.total_score >= 68 THEN 'WAITING_APPROVAL'\\n    ELSE 'MANUAL_REVIEW'\\n  END AS next_status,`;\n  out=replaceOnce(out,gateAnchor,gateReplacement,'language_gate_status');\n  out=replaceOnce(out,\"    CASE WHEN t.service_category='TRANSLATION' THEN 'تطابق مستقیم با خدمات ترجمه' END,\",\"    CASE WHEN t.service_category='TRANSLATION' THEN 'تطابق مستقیم با خدمات ترجمه' END,\\n    CASE WHEN t.service_category IN ('TRANSLATION','GENERAL_TRANSLATION') AND t.detected_language_source IS NOT NULL AND t.detected_language_target IS NOT NULL THEN 'زبان مبدأ و مقصد از متن پروژه استخراج شد' END,\",'language_reason');\n  out=replaceOnce(out,\"    CASE WHEN t.budget_toman_max IS NULL THEN 'بودجه اعلام نشده است' END,\",\"    CASE WHEN t.budget_toman_max IS NULL THEN 'بودجه اعلام نشده است' END,\\n    CASE WHEN t.service_category IN ('TRANSLATION','GENERAL_TRANSLATION') AND (t.detected_language_source IS NULL OR t.detected_language_target IS NULL) THEN 'زبان مبدأ و مقصد صریح مشخص نشده است' END,\",'language_risk');\n  out=replaceOnce(out,'  total_score=s.total_score,\\n  confidence_score=s.confidence_score,\\n  status=s.next_status,','  total_score=s.total_score,\\n  confidence_score=s.confidence_score,\\n  language_source=COALESCE(o.language_source,s.detected_language_source),\\n  language_target=COALESCE(o.language_target,s.detected_language_target),\\n  status=s.next_status,','language_update');\n  out=replaceOnce(out,\"    'subject_area',subject_area,\\n    'budget_toman_min',budget_toman_min,\",\"    'subject_area',subject_area,\\n    'language_source',detected_language_source,\\n    'language_target',detected_language_target,\\n    'budget_toman_min',budget_toman_min,\",'evaluation_snapshot_language');\n  out=replaceOnce(out,\"    'subject_area',s.subject_area,\\n    'budget_toman_min',s.budget_toman_min,\",\"    'subject_area',s.subject_area,\\n    'language_source',s.detected_language_source,\\n    'language_target',s.detected_language_target,\\n    'budget_toman_min',s.budget_toman_min,\",'outbox_language');\n  out=replaceOnce(out,\"FROM parscoders_scored s\\nON CONFLICT(idempotency_key) DO NOTHING;\",\"FROM parscoders_scored s\\nWHERE s.next_status='WAITING_APPROVAL'\\nON CONFLICT(idempotency_key) DO NOTHING;\",'outbox_waiting_only');\n  if(countOf(out,'rules-v4-parscoders')!==5)throw Error('rules_v4_occurrence_count_mismatch');\n  if(!out.includes('# compatibility-marker: rules-v3-parscoders'))throw Error('compat_marker_missing');\n  return out;\n}\n\nfunction psql(sql,{readOnly=false}={}){\n  const password=fs.readFileSync(PASSWORD_FILE,'utf8').trim();if(!password)throw Error('leadops_admin_password_empty');\n  const env={...process.env,PGPASSWORD:password,PGOPTIONS:readOnly?'-c default_transaction_read_only=on -c statement_timeout=15000 -c lock_timeout=2000':'-c statement_timeout=20000 -c lock_timeout=3000'};\n  const r=exec('/usr/bin/psql',['-X','-h','127.0.0.1','-p','55434','-U','leadops_admin','-d','leadops','-v','ON_ERROR_STOP=1','-At','-c',sql],{env,timeout:30000});\n  return String(r.stdout||'').trim();\n}\nfunction detectionSql(){\n  const src=sourceCase('corpus').replace(/^CASE\\n\\s*/,'CASE\\n        ');\n  const dst=targetCase('corpus').replace(/^CASE\\n\\s*/,'CASE\\n        ');\n  return `WITH c AS (\\n  SELECT o.id,lower(coalesce(o.title,'')||' '||coalesce(o.description,'')) AS corpus\\n  FROM automation.outbox_events e\\n  JOIN marketplace.opportunities o ON o.id=e.aggregate_id\\n  WHERE e.event_type='OpportunityDiscovered' AND e.status='pending' AND o.status='WAITING_APPROVAL'\\n    AND o.service_category IN ('TRANSLATION','GENERAL_TRANSLATION')\\n    AND (o.language_source IS NULL OR o.language_target IS NULL)\\n), d AS (SELECT id,${src} AS src,${dst} AS dst FROM c)\\nSELECT json_build_object('missing',count(*),'explicit',count(*) FILTER (WHERE src IS NOT NULL AND dst IS NOT NULL),'ambiguous',count(*) FILTER (WHERE src IS NULL OR dst IS NULL))::text FROM d`;\n}\nfunction migrationSql(){\n  const src=sourceCase('corpus').replace(/^CASE\\n\\s*/,'CASE\\n        ');\n  const dst=targetCase('corpus').replace(/^CASE\\n\\s*/,'CASE\\n        ');\n  return `BEGIN;\\nCREATE TEMP TABLE leadops_language_gate_targets ON COMMIT DROP AS\\nWITH c AS (\\n  SELECT DISTINCT o.id,lower(coalesce(o.title,'')||' '||coalesce(o.description,'')) AS corpus\\n  FROM automation.outbox_events e\\n  JOIN marketplace.opportunities o ON o.id=e.aggregate_id\\n  WHERE e.event_type='OpportunityDiscovered' AND e.status='pending' AND o.status='WAITING_APPROVAL'\\n    AND o.service_category IN ('TRANSLATION','GENERAL_TRANSLATION')\\n    AND (o.language_source IS NULL OR o.language_target IS NULL)\\n)\\nSELECT id,${src} AS detected_source,${dst} AS detected_target FROM c;\\nSELECT CASE WHEN count(*)<=${MAX_TARGETS} THEN 1 ELSE 1/0 END FROM leadops_language_gate_targets;\\nUPDATE marketplace.opportunities o SET\\n  language_source=t.detected_source,language_target=t.detected_target,\\n  classification_reasons=COALESCE(o.classification_reasons,'[]'::jsonb)||jsonb_build_array('language_direction_extracted:'||t.detected_source||'->'||t.detected_target),\\n  updated_at=now()\\nFROM leadops_language_gate_targets t\\nWHERE o.id=t.id AND t.detected_source IS NOT NULL AND t.detected_target IS NOT NULL;\\nUPDATE automation.outbox_events e SET\\n  payload=COALESCE(e.payload,'{}'::jsonb)||jsonb_build_object('language_source',t.detected_source,'language_target',t.detected_target)\\nFROM leadops_language_gate_targets t\\nWHERE e.aggregate_id=t.id AND e.event_type='OpportunityDiscovered' AND e.status='pending'\\n  AND t.detected_source IS NOT NULL AND t.detected_target IS NOT NULL;\\nUPDATE marketplace.opportunities o SET\\n  status='MANUAL_REVIEW',\\n  risk_flags=COALESCE(o.risk_flags,'[]'::jsonb)||jsonb_build_array('language_direction_missing'),\\n  classification_reasons=COALESCE(o.classification_reasons,'[]'::jsonb)||jsonb_build_array('manual_review:language_direction_missing'),\\n  updated_at=now()\\nFROM leadops_language_gate_targets t\\nWHERE o.id=t.id AND (t.detected_source IS NULL OR t.detected_target IS NULL);\\nUPDATE automation.outbox_events e SET status='cancelled',last_error='language_direction_missing'\\nFROM leadops_language_gate_targets t\\nWHERE e.aggregate_id=t.id AND e.event_type='OpportunityDiscovered' AND e.status='pending'\\n  AND (t.detected_source IS NULL OR t.detected_target IS NULL);\\nINSERT INTO audit.audit_log(actor_type,actor_id,action,entity_type,entity_id,after_data,correlation_id)\\nSELECT 'automation','host-action:leadops_language_gate_v1','LEADOPS_LANGUAGE_DIRECTION_ENRICHED','opportunity',t.id,\\n       jsonb_build_object('language_source',t.detected_source,'language_target',t.detected_target),\\n       'host-action:leadops_language_gate_v1'\\nFROM leadops_language_gate_targets t WHERE t.detected_source IS NOT NULL AND t.detected_target IS NOT NULL;\\nINSERT INTO audit.audit_log(actor_type,actor_id,action,entity_type,entity_id,after_data,correlation_id)\\nSELECT 'automation','host-action:leadops_language_gate_v1','LEADOPS_LANGUAGE_DIRECTION_MANUAL_REVIEW','opportunity',t.id,\\n       jsonb_build_object('status','MANUAL_REVIEW','reason','language_direction_missing'),\\n       'host-action:leadops_language_gate_v1'\\nFROM leadops_language_gate_targets t WHERE t.detected_source IS NULL OR t.detected_target IS NULL;\\nSELECT CASE WHEN count(*)=0 THEN 1 ELSE 1/0 END\\nFROM marketplace.opportunities o\\nWHERE o.status='WAITING_APPROVAL' AND o.service_category IN ('TRANSLATION','GENERAL_TRANSLATION')\\n  AND (o.language_source IS NULL OR o.language_target IS NULL)\\n  AND EXISTS (SELECT 1 FROM automation.outbox_events e WHERE e.aggregate_id=o.id AND e.event_type='OpportunityDiscovered' AND e.status='pending');\\nSELECT CASE WHEN count(*)=0 THEN 1 ELSE 1/0 END\\nFROM automation.outbox_events e JOIN marketplace.opportunities o ON o.id=e.aggregate_id\\nWHERE e.event_type='OpportunityDiscovered' AND e.status='pending' AND o.status='MANUAL_REVIEW'\\n  AND o.risk_flags ? 'language_direction_missing';\\nSELECT json_build_object(\\n  'targets',(SELECT count(*) FROM leadops_language_gate_targets),\\n  'enriched',(SELECT count(*) FROM leadops_language_gate_targets WHERE detected_source IS NOT NULL AND detected_target IS NOT NULL),\\n  'manual_review',(SELECT count(*) FROM leadops_language_gate_targets WHERE detected_source IS NULL OR detected_target IS NULL)\\n)::text;\\nCOMMIT;`;\n}\nfunction parseLastJson(text){const lines=String(text||'').split(/\\r?\\n/).map(x=>x.trim()).filter(Boolean);for(let i=lines.length-1;i>=0;i--){try{return JSON.parse(lines[i]);}catch{}}throw Error('json_summary_missing');}\nfunction preflight(){\n  const actual=shaFile(SCORER);if(actual!==EXPECTED_V3_SHA)throw Error('runtime_scorer_sha_mismatch:'+actual);\n  const source=fs.readFileSync(SCORER,'utf8');const candidate=buildScorerV4(source);\n  const tmp='/tmp/leadops-parscoders-score-v4-preflight-'+process.pid;fs.writeFileSync(tmp,candidate,{mode:0o600});try{exec('/usr/bin/bash',['-n',tmp],{timeout:10000});}finally{try{fs.unlinkSync(tmp)}catch{}}\n  const db=parseLastJson(psql(detectionSql(),{readOnly:true}));if(Number(db.missing)>MAX_TARGETS)throw Error('leadops_language_targets_exceed_limit:'+db.missing);\n  return {ok:true,action:ACTION,preflight_only:true,current_scorer_sha256:actual,candidate_scorer_sha256:shaBuffer(Buffer.from(candidate)),scoring_model:'rules-v4-parscoders',language_codes:'ISO-639-1 lowercase',targets:db};\n}\nfunction atomicReplace(file,text){const st=fs.statSync(file);const tmp=file+'.language-gate-'+process.pid+'-'+Date.now()+'.tmp';fs.writeFileSync(tmp,text,{mode:st.mode&0o777});fs.chownSync(tmp,st.uid,st.gid);fs.renameSync(tmp,file);}\nfunction main(){\n  if(process.argv.includes('--preflight-only')){console.log(JSON.stringify(preflight()));return;}\n  fs.mkdirSync(STATE_DIR,{recursive:true,mode:0o700});\n  try{fs.mkdirSync(LOCK_DIR,{mode:0o700});}catch(e){if(e.code==='EEXIST')throw Error('leadops_language_gate_already_running');throw e;}\n  let backup=null,patched=false,agentRestarted=false;\n  try{\n    const svc=systemctl(['is-active','leadops-parscoders-v3.service'],{allowFailure:true,timeout:10000});if(String(svc.stdout||'').trim()==='active')throw Error('parscoders_v3_service_active_retry_later');\n    const pf=preflight();\n    const source=fs.readFileSync(SCORER,'utf8');const candidate=buildScorerV4(source);\n    systemctl(['stop','leadops-parscoders-v3.timer'],{allowFailure:true,timeout:15000});\n    backup=path.join(STATE_DIR,'leadops-parscoders-score-v3-'+Date.now()+'.bak');fs.copyFileSync(SCORER,backup,fs.constants.COPYFILE_EXCL);fs.chmodSync(backup,0o600);\n    atomicReplace(SCORER,candidate);patched=true;exec('/usr/bin/bash',['-n',SCORER],{timeout:10000});\n    systemctl(['restart','prhm-agent-api.service'],{timeout:30000});agentRestarted=true;\n    if(!waitActive('prhm-agent-api.service'))throw Error('agent_api_not_active_after_scorer_v4');\n    if(!waitActive('leadops-parscoders-v3.timer'))throw Error('parscoders_timer_not_active_after_scorer_v4');\n    const migration=parseLastJson(psql(migrationSql()));\n    const finalCheck=parseLastJson(psql(detectionSql(),{readOnly:true}));\n    if(Number(finalCheck.missing)!==0)throw Error('language_gate_postcheck_missing:'+finalCheck.missing);\n    const result={schema_version:'prhm.host-action-result.v1',ok:true,action:ACTION,finished_at:new Date().toISOString(),scorer_before_sha256:EXPECTED_V3_SHA,scorer_after_sha256:shaFile(SCORER),scoring_model:'rules-v4-parscoders',language_codes:'ISO-639-1 lowercase',migration,remaining_waiting_missing_language:0,timer:'leadops-parscoders-v3.timer',timer_active:true,p0_live:false,proposal_send:false,bid_send:false,backup_path:backup,rollback_performed:false,preflight:pf.targets};\n    try{const tmp=RESULT_FILE+'.'+process.pid+'.tmp';fs.writeFileSync(tmp,JSON.stringify(result)+'\\n',{mode:0o600});fs.renameSync(tmp,RESULT_FILE);}catch(e){console.error(JSON.stringify({event:'leadops_language_gate_result_persist_warning',message:e.message}));}\n    console.log(JSON.stringify(result));\n  }catch(error){\n    const rollbackErrors=[];\n    if(patched&&backup){try{const old=fs.readFileSync(backup);atomicReplace(SCORER,old.toString('utf8'));}catch(e){rollbackErrors.push('scorer:'+e.message)}}\n    try{systemctl(['restart','prhm-agent-api.service'],{timeout:30000});if(!waitActive('prhm-agent-api.service'))throw Error('agent_api_not_active')}catch(e){rollbackErrors.push('agent_api:'+e.message)}\n    if(rollbackErrors.length)throw Error('leadops_language_gate_failed_and_rollback_failed:'+error.message+':'+rollbackErrors.join('|'));\n    throw Error('leadops_language_gate_failed_rolled_back:'+error.message);\n  }finally{try{fs.rmdirSync(LOCK_DIR)}catch{}}\n}\nmain();\n";

function shaText(s){return crypto.createHash('sha256').update(Buffer.from(s,'utf8')).digest('hex');}
function read(f){return fs.readFileSync(f,'utf8');}
function assertSha(label,file,expected){const actual=shaText(read(file));if(actual!==expected)throw Error(`sha_mismatch:${label}:${actual}`);}
function replaceOnce(text,anchor,replacement,label){const i=text.indexOf(anchor);if(i<0)throw Error(`anchor_missing:${label}`);if(text.indexOf(anchor,i+anchor.length)>=0)throw Error(`anchor_not_unique:${label}`);return text.slice(0,i)+replacement+text.slice(i+anchor.length);}
function insertAfterUniqueLine(text,needle,line,label){const rows=text.split('\n');const idx=[];rows.forEach((r,i)=>{if(r.includes(needle))idx.push(i)});if(idx.length!==1)throw Error(`line_anchor_count:${label}:${idx.length}`);const i=idx[0];if(!rows[i].trim().endsWith('}'))throw Error(`line_anchor_shape:${label}`);rows[i]=rows[i]+',';rows.splice(i+1,0,line);return rows.join('\n');}
function writeAtomic(file,text,mode,uid,gid){const tmp=`${file}.host-actions-v3-${process.pid}-${Date.now()}.tmp`;fs.writeFileSync(tmp,text,{mode});fs.chmodSync(tmp,mode);fs.chownSync(tmp,uid,gid);fs.renameSync(tmp,file);}
function backupFile(file,dir){const dest=path.join(dir,file.replace(/^\//,'').replace(/\//g,'__'));fs.copyFileSync(file,dest,fs.constants.COPYFILE_EXCL);fs.chmodSync(dest,0o600);return dest;}
function restore(file,backup){const st=fs.statSync(file);const data=fs.readFileSync(backup);const tmp=`${file}.rollback-${process.pid}-${Date.now()}.tmp`;fs.writeFileSync(tmp,data,{mode:st.mode&0o777});fs.chownSync(tmp,st.uid,st.gid);fs.renameSync(tmp,file);}
function nodeCheck(file){cp.execFileSync('/usr/local/bin/prhm-node',['--check',file],{stdio:'pipe',timeout:15000});}
function systemctl(...args){return cp.execFileSync('systemctl',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:30000}).trim();}
function curlUnix(socket,url){return cp.execFileSync('curl',['-fsS','--max-time','5','--unix-socket',socket,url],{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:8000}).trim();}
function sleep(ms){Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,ms);}
function waitFor(fn,attempts=30,delay=500){let last;for(let i=0;i<attempts;i++){try{const x=fn();if(x)return x;}catch(e){last=e}sleep(delay);}throw last||Error('health_timeout');}

function patchPolicy(input){const p=JSON.parse(input);if(p.schema_version!=='prhm.approval-policy.v1')throw Error('unexpected_policy_schema');p.version=VERSION;p.operations=p.operations||{};p.typed_scopes=Array.isArray(p.typed_scopes)?p.typed_scopes:[];p.operations[OPERATION]={level:4};const matches=p.typed_scopes.filter(x=>x&&x.tool==='host_action_v2_apply'&&x.project==='control_plane'&&x.environment==='production'&&x.action===ACTION&&x.risk==='critical'&&x.operation===OPERATION);if(matches.length>1)throw Error('duplicate_scope:'+ACTION);if(matches.length===0)p.typed_scopes.push({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'critical',operation:OPERATION,principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});return JSON.stringify(p,null,2)+'\n';}
